import{c as t,Q as a,j as r,m as n}from"./chunks/framework.BXc4yaFE.js";const d=JSON.parse('{"title":"Agent Memory Below the Prompt: Persistent Q4 KV Cache for Multi-Agent LLM Inference on Edge Devices","description":"","frontmatter":{"url":"https://arxiv.org/abs/2603.04428","title":"Agent Memory Below the Prompt: Persistent Q4 KV Cache for Multi-Agent LLM Inference on Edge Devices","arxiv_id":2603.04428,"collected_at":"2026-08-02T00:00:00.000Z","collected_by":"routine-d","domain":"Caching / KV Cache / Token Budget","pdf_path":"pdfs/2603.04428.pdf","year":2026},"headers":[],"relativePath":"research/papers/2026-02-17-agent-memory-below-prompt-persistent-q4-kv-cache-2603-04428.md","filePath":"research/papers/2026-02-17-agent-memory-below-prompt-persistent-q4-kv-cache-2603-04428.md","lastUpdated":1785909234000}'),o={name:"research/papers/2026-02-17-agent-memory-below-prompt-persistent-q4-kv-cache-2603-04428.md"};function s(c,e,i,p,l,m){return a(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="agent-memory-below-the-prompt-persistent-q4-kv-cache-for-multi-agent-llm-inference-on-edge-devices" tabindex="-1">Agent Memory Below the Prompt: Persistent Q4 KV Cache for Multi-Agent LLM Inference on Edge Devices <a class="header-anchor" href="#agent-memory-below-the-prompt-persistent-q4-kv-cache-for-multi-agent-llm-inference-on-edge-devices" aria-label="Permalink to &quot;Agent Memory Below the Prompt: Persistent Q4 KV Cache for Multi-Agent LLM Inference on Edge Devices&quot;">​</a></h1><h2 id="摘要-核心貢獻" tabindex="-1">摘要 / 核心貢獻 <a class="header-anchor" href="#摘要-核心貢獻" aria-label="Permalink to &quot;摘要 / 核心貢獻&quot;">​</a></h2><p>邊緣裝置（如 Apple M4 Pro）跑多代理 LLM 系統時，RAM 容量是硬限制：實測只能同時容納 3 個 agent 的 KV cache，第 4 個以後就得整段重新 prefill，成本極高。本論文提出把 量化後的 KV cache（4-bit，Q4）持久化落盤，跳過昂貴的重新 prefill，讓同一裝置可同時 維持 10+ 個 agent 的上下文狀態。</p><p>系統含三個元件：<strong>block pool</strong>（以 safetensors 格式隔離儲存各 agent 的 Q4 KV cache）、 <strong>BatchQuantizedKVCache</strong>（支援多 agent 併發推理的批次量化快取管理）、以及 <strong>cross-phase context injection</strong>（跨階段注入累積的 attention 狀態而不必重算）。 實測在 Gemma 3 12B、DeepSeek-Coder-V2-Lite 16B、Llama 3.1 8B 三種架構上：快取還原 達最高 136× 的 TTFT 加速（Gemma 32K context），4-bit 量化讓可同時容納的 agent 數量比 FP16 多 4 倍，且困惑度（perplexity）影響極小（Gemma -0.7%、Llama +2.8%、 DeepSeek +3.0%）。</p><h2 id="與-harness-的關聯" tabindex="-1">與 Harness 的關聯 <a class="header-anchor" href="#與-harness-的關聯" aria-label="Permalink to &quot;與 Harness 的關聯&quot;">​</a></h2><p>本 workspace 的多代理編排（sub-agent 委派、Workflow pipeline）在單機/資源受限環境下 會遇到與本論文相同的「同時維持多個 agent context」瓶頸；量化 KV cache 持久化落盤的 做法，為未來若需在本地/邊緣環境擴大並行 sub-agent 數量時，提供了具體可行的成本-延遲 權衡參照數據。</p>',6)])])}const g=t(o,[["render",s]]);export{d as __pageData,g as default};
